import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { openDatabase, toJob, type JobRow } from './db.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');
const MAX_BODY = 1024 * 1024;
const HEARTBEAT_WINDOW_MS = 3000;

interface FieldError {
  field: string;
  message: string;
}

class HttpError extends Error {
  constructor(
    public status: number,
    public code: string,
    message: string,
    public fields?: FieldError[],
  ) {
    super(message);
  }
}

function send(res: ServerResponse, status: number, body: unknown, headers: Record<string, string> = {}): void {
  const data = JSON.stringify(body);
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store', ...headers });
  res.end(data);
}

function sendError(res: ServerResponse, err: HttpError): void {
  const error: Record<string, unknown> = { code: err.code, message: err.message };
  if (err.fields || err.code === 'invalid_request') error.fields = err.fields ?? [];
  send(res, err.status, { error }, err.status === 405 ? { allow: (err as HttpError & { allow?: string }).allow ?? '' } : {});
}

function invalid(fields: FieldError[]): HttpError {
  return new HttpError(400, 'invalid_request', fields.map((f) => `${f.field}: ${f.message}`).join('; '), fields);
}

function readBody(req: IncomingMessage): Promise<string> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY) tooLarge = true;
      else chunks.push(chunk);
    });
    req.on('end', () => {
      if (tooLarge) reject(invalid([{ field: 'body', message: 'Request body is too large.' }]));
      else resolve(Buffer.concat(chunks).toString('utf8'));
    });
    req.on('error', reject);
  });
}

interface Payload {
  input: string;
  steps: number;
  failAttempts: number;
}

function validate(body: unknown): Payload {
  if (typeof body !== 'object' || body === null || Array.isArray(body)) {
    throw invalid([{ field: 'body', message: 'Body must be a JSON object.' }]);
  }
  const obj = body as Record<string, unknown>;
  const fields: FieldError[] = [];
  for (const key of Object.keys(obj)) {
    if (!['input', 'steps', 'failAttempts'].includes(key)) fields.push({ field: key, message: 'Unknown field.' });
  }
  const input = obj.input;
  if (input === undefined) fields.push({ field: 'input', message: 'input is required.' });
  else if (typeof input !== 'string') fields.push({ field: 'input', message: 'input must be a string.' });
  else if (input.length < 1 || input.length > 1000) fields.push({ field: 'input', message: 'input must be 1-1000 characters.' });
  else if (input.trim().length === 0) fields.push({ field: 'input', message: 'input must not be only whitespace.' });

  const intField = (name: 'steps' | 'failAttempts', min: number, max: number, def: number): number => {
    const v = obj[name];
    if (v === undefined) return def;
    if (typeof v !== 'number' || !Number.isInteger(v) || v < min || v > max) {
      fields.push({ field: name, message: `${name} must be an integer from ${min} to ${max}.` });
      return def;
    }
    return v;
  };
  const steps = intField('steps', 1, 20, 5);
  const failAttempts = intField('failAttempts', 0, 5, 0);
  if (fields.length) throw invalid(fields);
  return { input: input as string, steps, failAttempts };
}

const selectById = db.prepare('SELECT * FROM jobs WHERE id = ?');
const selectByKey = db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?');
const selectAll = db.prepare('SELECT * FROM jobs ORDER BY seq DESC');
const insertJob = db.prepare(
  `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress, created_at, updated_at, run_after, idempotency_key, payload)
   VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, ?, 0, ?, ?) RETURNING *`,
);
const selectHeartbeat = db.prepare('SELECT at FROM heartbeat WHERE id = 1');

async function createJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const fields: FieldError[] = [];
  const rawKey = req.headers['idempotency-key'];
  let key: string | null = null;
  if (rawKey !== undefined) {
    const k = Array.isArray(rawKey) ? rawKey.join(',') : rawKey;
    if (!/^[A-Za-z0-9_-]{1,128}$/.test(k)) {
      fields.push({ field: 'Idempotency-Key', message: 'Idempotency-Key must match ^[A-Za-z0-9_-]{1,128}$.' });
    } else key = k;
  }
  const contentType = (req.headers['content-type'] ?? '').split(';')[0]!.trim().toLowerCase();
  const isJson = contentType === 'application/json' || /^application\/[a-z0-9.+-]+\+json$/.test(contentType);
  const raw = await readBody(req);
  if (!isJson) {
    fields.push({ field: 'body', message: 'Content-Type must be application/json.' });
    throw invalid(fields);
  }
  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch {
    fields.push({ field: 'body', message: 'Body is not valid JSON.' });
    throw invalid(fields);
  }
  let payload: Payload;
  try {
    payload = validate(parsed);
  } catch (err) {
    if (err instanceof HttpError && err.fields) throw invalid([...fields, ...err.fields]);
    throw err;
  }
  if (fields.length) throw invalid(fields);

  const payloadJson = JSON.stringify([payload.input, payload.steps, payload.failAttempts]);
  if (key !== null) {
    const existing = selectByKey.get(key) as (JobRow & { payload: string }) | undefined;
    if (existing) {
      if (existing.payload === payloadJson) return send(res, 200, toJob(existing));
      throw new HttpError(409, 'idempotency_conflict', 'Idempotency-Key was already used with a different payload.');
    }
  }
  const ts = new Date().toISOString();
  try {
    const row = insertJob.get(randomUUID(), payload.input, payload.steps, payload.failAttempts, ts, ts, key, payloadJson) as JobRow;
    send(res, 201, toJob(row));
  } catch (err) {
    // A concurrent insert with the same key (e.g. another server process) wins; replay it.
    if (key !== null) {
      const existing = selectByKey.get(key) as (JobRow & { payload: string }) | undefined;
      if (existing) {
        if (existing.payload === payloadJson) return send(res, 200, toJob(existing));
        throw new HttpError(409, 'idempotency_conflict', 'Idempotency-Key was already used with a different payload.');
      }
    }
    throw err;
  }
}

function methodNotAllowed(allow: string): HttpError {
  const e = new HttpError(405, 'method_not_allowed', 'Method not allowed.');
  (e as HttpError & { allow?: string }).allow = allow;
  return e;
}

async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method ?? 'GET';
  const isGet = method === 'GET' || method === 'HEAD';

  if (pathname === '/') {
    if (!isGet) throw methodNotAllowed('GET');
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8', 'cache-control': 'no-store' });
    res.end(uiHtml);
    return;
  }
  if (pathname === '/health') {
    if (!isGet) throw methodNotAllowed('GET');
    const hb = selectHeartbeat.get() as { at: number } | undefined;
    const up = !!hb && Date.now() - hb.at <= HEARTBEAT_WINDOW_MS;
    return send(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
  }
  if (pathname === '/api/jobs') {
    if (method === 'POST') return createJob(req, res);
    if (!isGet) throw methodNotAllowed('GET, POST');
    const rows = selectAll.all() as unknown as JobRow[];
    return send(res, 200, { jobs: rows.map(toJob) });
  }
  const m = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (m) {
    if (!isGet) throw methodNotAllowed('GET');
    let id: string;
    try {
      id = decodeURIComponent(m[1]!);
    } catch {
      throw new HttpError(404, 'not_found', 'Job not found.');
    }
    const row = selectById.get(id) as JobRow | undefined;
    if (!row) throw new HttpError(404, 'not_found', 'Job not found.');
    return send(res, 200, toJob(row));
  }
  throw new HttpError(404, 'not_found', 'Not found.');
}

const port = Number(process.env.PORT || 3000);
const server = createServer((req, res) => {
  handle(req, res).catch((err: unknown) => {
    if (res.headersSent) {
      res.destroy();
      return;
    }
    if (err instanceof HttpError) return sendError(res, err);
    console.error(err);
    sendError(res, new HttpError(500, 'internal_error', 'Internal server error.'));
  });
});
server.listen(port, () => console.log(`server listening on ${port}`));

let shuttingDown = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    if (shuttingDown) return;
    shuttingDown = true;
    server.close(() => {
      try {
        db.close();
      } catch {}
      process.exit(0);
    });
    server.closeIdleConnections();
    setTimeout(() => {
      server.closeAllConnections();
    }, 2000).unref();
    setTimeout(() => process.exit(0), 5000).unref();
  });
}

